-- 阶段 1：仅执行本段；管理员核对版本及实际列后，再单独执行阶段 2。
SET SESSION TRANSACTION READ ONLY;
SELECT VERSION() AS version, @@sql_mode AS sql_mode, @@character_set_server AS charset_server, @@collation_server AS collation_server;
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('leads','lead_hunt_candidates') ORDER BY TABLE_NAME,ORDINAL_POSITION;

-- 阶段 2：只读账号执行；无新迁移列依赖；每类抽样最多 20 条；电话仅显示后四位。

-- FAX_LABEL
SELECT 'FAX_LABEL' AS flag,COUNT(*) AS row_count FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (LOCATE(c.phone,c.snippet)>0 AND LOWER(SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-30),LEAST(30,LOCATE(c.phone,c.snippet)-1))) REGEXP '传[[:space:]]*真|fax');
SELECT 'FAX_LABEL' AS flag,c.entityType,c.id,c.companyName,CONCAT('****',RIGHT(c.phone,4)) AS phone_last4,c.assignedUserId FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (LOCATE(c.phone,c.snippet)>0 AND LOWER(SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-30),LEAST(30,LOCATE(c.phone,c.snippet)-1))) REGEXP '传[[:space:]]*真|fax') ORDER BY c.entityType,c.id LIMIT 20;

-- NO_NEARBY_NAME
SELECT 'NO_NEARBY_NAME' AS flag,COUNT(*) AS row_count FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (LOCATE(c.phone,c.snippet)>0 AND (NULLIF(TRIM(c.companyName),'') IS NULL OR LOCATE(c.companyName,SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-80),LEAST(80,LOCATE(c.phone,c.snippet)-1)+CHAR_LENGTH(c.phone)+80))=0));
SELECT 'NO_NEARBY_NAME' AS flag,c.entityType,c.id,c.companyName,CONCAT('****',RIGHT(c.phone,4)) AS phone_last4,c.assignedUserId FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (LOCATE(c.phone,c.snippet)>0 AND (NULLIF(TRIM(c.companyName),'') IS NULL OR LOCATE(c.companyName,SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-80),LEAST(80,LOCATE(c.phone,c.snippet)-1)+CHAR_LENGTH(c.phone)+80))=0)) ORDER BY c.entityType,c.id LIMIT 20;

-- SHARED_PHONE
SELECT 'SHARED_PHONE' AS flag,COUNT(*) AS row_count FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (c.phone IN (SELECT p.phone FROM (SELECT phone,companyName FROM leads UNION ALL SELECT phone,companyName FROM lead_hunt_candidates) p WHERE NULLIF(TRIM(p.phone),'') IS NOT NULL GROUP BY p.phone HAVING COUNT(DISTINCT p.companyName)>1));
SELECT 'SHARED_PHONE' AS flag,c.entityType,c.id,c.companyName,CONCAT('****',RIGHT(c.phone,4)) AS phone_last4,c.assignedUserId FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (c.phone IN (SELECT p.phone FROM (SELECT phone,companyName FROM leads UNION ALL SELECT phone,companyName FROM lead_hunt_candidates) p WHERE NULLIF(TRIM(p.phone),'') IS NOT NULL GROUP BY p.phone HAVING COUNT(DISTINCT p.companyName)>1)) ORDER BY c.entityType,c.id LIMIT 20;

-- ASSIGNED_FLAGGED
SELECT 'ASSIGNED_FLAGGED' AS flag,COUNT(*) AS row_count FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (c.assignedUserId IS NOT NULL AND ((LOCATE(c.phone,c.snippet)>0 AND LOWER(SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-30),LEAST(30,LOCATE(c.phone,c.snippet)-1))) REGEXP '传[[:space:]]*真|fax') OR (LOCATE(c.phone,c.snippet)>0 AND (NULLIF(TRIM(c.companyName),'') IS NULL OR LOCATE(c.companyName,SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-80),LEAST(80,LOCATE(c.phone,c.snippet)-1)+CHAR_LENGTH(c.phone)+80))=0)) OR (c.phone IN (SELECT p.phone FROM (SELECT phone,companyName FROM leads UNION ALL SELECT phone,companyName FROM lead_hunt_candidates) p WHERE NULLIF(TRIM(p.phone),'') IS NOT NULL GROUP BY p.phone HAVING COUNT(DISTINCT p.companyName)>1))));
SELECT 'ASSIGNED_FLAGGED' AS flag,c.entityType,c.id,c.companyName,CONCAT('****',RIGHT(c.phone,4)) AS phone_last4,c.assignedUserId FROM (SELECT 'candidate' AS entityType,h.id,h.companyName,h.phone,h.snippet,l.assignedUserId FROM lead_hunt_candidates h LEFT JOIN leads l ON l.id=h.leadId UNION ALL SELECT 'lead',id,companyName,phone,NULL,assignedUserId FROM leads) c WHERE NULLIF(TRIM(c.phone),'') IS NOT NULL AND (c.assignedUserId IS NOT NULL AND ((LOCATE(c.phone,c.snippet)>0 AND LOWER(SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-30),LEAST(30,LOCATE(c.phone,c.snippet)-1))) REGEXP '传[[:space:]]*真|fax') OR (LOCATE(c.phone,c.snippet)>0 AND (NULLIF(TRIM(c.companyName),'') IS NULL OR LOCATE(c.companyName,SUBSTRING(c.snippet,GREATEST(1,LOCATE(c.phone,c.snippet)-80),LEAST(80,LOCATE(c.phone,c.snippet)-1)+CHAR_LENGTH(c.phone)+80))=0)) OR (c.phone IN (SELECT p.phone FROM (SELECT phone,companyName FROM leads UNION ALL SELECT phone,companyName FROM lead_hunt_candidates) p WHERE NULLIF(TRIM(p.phone),'') IS NOT NULL GROUP BY p.phone HAVING COUNT(DISTINCT p.companyName)>1)))) ORDER BY c.entityType,c.id LIMIT 20;
